    });
  }

  // ══════════════════════════════════════════════════════════════════════
  // SLIDE 3 — Top 5 Repos by Total Score (Horizontal Bar Chart)
  // ══════════════════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    slide.addText("hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.65,
      fontSize: 24, fontFace: "Trebuchet MS", color: C.navy, bold: true, margin: 0
    });

    // Ranked table approach — more readable than a chart
    const repos = [
      { rank: "#1", name: "NousResearch/hermes-agent", desc: "The agent that grows with you", stars: "1,347", forks: "101", pushes: "42", prs: "78", lang: "Python" },
