const pptxgen = require("pptxgenjs");
const React = require("react");
const ReactDOMServer = require("react-dom/server");
const sharp = require("sharp");

// Icon imports
const { FaDatabase, FaStar, FaCodeBranch, FaArrowUp, FaCode, FaPython, FaRobot } = require("react-icons/fa");
const { MdInsights, MdTrendingUp, MdCategory, MdPeople, MdLightbulb } = require("react-icons/md");
const { HiChartBar, HiLightningBolt } = require("react-icons/hi");

// ── Icon rendering ──
function renderIconSvg(IconComponent, color = "#000000", size = 256) {
  return ReactDOMServer.renderToStaticMarkup(
    React.createElement(IconComponent, { color, size: String(size) })
  );
}

async function iconToBase64Png(IconComponent, color, size = 256) {
  const svg = renderIconSvg(IconComponent, color, size);
  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
  return "image/png;base64," + pngBuffer.toString("base64");
}

// ── Color palette: "Midnight Executive" adapted for data/tech ──
const C = {
  navy:      "0F172A",
  darkSlate: "1E293B",
  slate:     "334155",
  midGray:   "64748B",
  lightGray: "94A3B8",
  offWhite:  "F1F5F9",
  white:     "FFFFFF",
  teal:      "0D9488",
  tealLight: "14B8A6",
  tealPale:  "CCFBF1",
  amber:     "F59E0B",
  amberPale: "FEF3C7",
  blue:      "3B82F6",
  purple:    "8B5CF6",
  rose:      "F43F5E",
  green:     "22C55E",
  indigo:    "6366F1",
  orange:    "F97316",
  cyan:      "06B6D4",
  pink:      "EC4899",
};

const makeShadow = () => ({ type: "outer", blur: 6, offset: 2, angle: 135, color: "000000", opacity: 0.12 });

async function main() {
  const pres = new pptxgen();
  pres.layout = "LAYOUT_16x9";
  pres.author = "OSSInsight Analysis";
  pres.title = "GitHub Trending Repos Snapshot: The Rise of AI Coding Agents & Claude Code Skills";

  // ── Pre-render icons ──
  const icons = {};
  const iconMap = {
    database: [FaDatabase, "#" + C.tealLight],
    star: [FaStar, "#" + C.amber],
    fork: [FaCodeBranch, "#" + C.tealLight],
    trending: [MdTrendingUp, "#" + C.white],
    category: [MdCategory, "#" + C.white],
    people: [MdPeople, "#" + C.white],
    lightbulb: [MdLightbulb, "#" + C.amber],
    insights: [MdInsights, "#" + C.tealLight],
    chart: [HiChartBar, "#" + C.tealLight],
    code: [FaCode, "#" + C.tealLight],
    robot: [FaRobot, "#" + C.tealLight],
    lightning: [HiLightningBolt, "#" + C.amber],
  };
  for (const [key, [Comp, color]] of Object.entries(iconMap)) {
    icons[key] = await iconToBase64Png(Comp, color, 256);
  }

  // ══════════════════════════════════════════════════════════════════════
  // SLIDE 1 — Title
  // ══════════════════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.navy };

    // Decorative top bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    // Subtle grid pattern (decorative lines)
    for (let i = 0; i < 5; i++) {
      slide.addShape(pres.shapes.RECTANGLE, {
        x: 0, y: 1.0 + i * 0.9, w: 10, h: 0.003,
        fill: { color: C.slate, transparency: 70 }
      });
    }

    slide.addText("GitHub Trending Repos Snapshot", {
      x: 0.8, y: 1.1, w: 8.4, h: 1.2,
      fontSize: 38, fontFace: "Trebuchet MS", color: C.white, bold: true,
      margin: 0
    });

    slide.addText("The Rise of AI Coding Agents & Claude Code Skills", {
      x: 0.8, y: 2.3, w: 8.4, h: 0.6,
      fontSize: 20, fontFace: "Calibri", color: C.tealLight,
      margin: 0
    });

    // Divider line
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: 3.15, w: 2.5, h: 0.04, fill: { color: C.teal }
    });

    slide.addText("Data sourced from OSSInsight  |  10.6B+ GitHub events tracked", {
      x: 0.8, y: 3.45, w: 8.4, h: 0.5,
      fontSize: 13, fontFace: "Calibri", color: C.lightGray,
      margin: 0
    });

    slide.addText("Top 20 Trending Repositories  |  Past 24 Hours  |  All Languages", {
      x: 0.8, y: 3.9, w: 8.4, h: 0.5,
      fontSize: 12, fontFace: "Calibri", color: C.midGray,
      margin: 0
    });

    // Icon cluster bottom-right
    slide.addImage({ data: icons.trending, x: 8.4, y: 4.1, w: 0.7, h: 0.7 });

    // Bottom accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 5.425, w: 10, h: 0.2, fill: { color: C.darkSlate }
    });
  }

  // ══════════════════════════════════════════════════════════════════════
  // SLIDE 2 — OSSInsight Platform Overview
  // ══════════════════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    // Top accent bar
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    slide.addText("OSSInsight Tracks 10.6 Billion GitHub Events in Real Time", {
      x: 0.8, y: 0.35, w: 8.4, h: 0.7,
      fontSize: 28, fontFace: "Trebuchet MS", color: C.navy, bold: true, margin: 0
    });

    slide.addText("A free, real-time analytics platform providing deep insights into open-source repositories, developers, and organizations.", {
      x: 0.8, y: 1.1, w: 8.4, h: 0.5,
      fontSize: 14, fontFace: "Calibri", color: C.midGray, margin: 0
    });

    // Stat cards
    const stats = [
      { value: "10.6B+", label: "GitHub Events\nTracked", icon: icons.database, bg: C.navy },
      { value: "6", label: "Core Metrics\nStars · Commits · PRs\nIssues · Reviews · Forks", icon: icons.insights, bg: C.darkSlate },
      { value: "24h", label: "Trending\nWindow", icon: icons.chart, bg: C.slate },
    ];

    const cardW = 2.6, cardH = 2.4, gap = 0.35;
    const totalW = stats.length * cardW + (stats.length - 1) * gap;
    const startX = (10 - totalW) / 2;

    stats.forEach((s, i) => {
      const cx = startX + i * (cardW + gap);
      const cy = 1.9;

      slide.addShape(pres.shapes.RECTANGLE, {
        x: cx, y: cy, w: cardW, h: cardH,
        fill: { color: s.bg },
        shadow: makeShadow()
      });

      slide.addImage({ data: s.icon, x: cx + (cardW - 0.5) / 2, y: cy + 0.3, w: 0.5, h: 0.5 });

      slide.addText(s.value, {
        x: cx, y: cy + 0.9, w: cardW, h: 0.7,
        fontSize: 36, fontFace: "Trebuchet MS", color: C.white, bold: true,
        align: "center", valign: "middle", margin: 0
      });

      slide.addText(s.label, {
        x: cx + 0.2, y: cy + 1.6, w: cardW - 0.4, h: 0.65,
        fontSize: 11, fontFace: "Calibri", color: C.lightGray,
        align: "center", valign: "top", margin: 0
      });
    });

    // Scoring formula
    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0.8, y: 4.6, w: 8.4, h: 0.7,
      fill: { color: C.white },
      shadow: makeShadow()
    });
    slide.addText([
      { text: "Ranking Formula:  ", options: { bold: true, color: C.navy, fontSize: 13 } },
      { text: "Total Score = Stars Score + Forks Score + Base Score", options: { color: C.teal, fontSize: 13, bold: true } },
      { text: "   —  composite metric weighting community traction", options: { color: C.midGray, fontSize: 11 } }
    ], {
      x: 1.0, y: 4.6, w: 8.0, h: 0.7,
      fontFace: "Calibri", valign: "middle", margin: 0
    });
  }

  // ══════════════════════════════════════════════════════════════════════
  // SLIDE 3 — Top 5 Repos by Total Score (Horizontal Bar Chart)
  // ══════════════════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    slide.addText("hermes-agent Leads with 1,347 Stars — Top 5 Repos by Total Score", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.65,
      fontSize: 24, fontFace: "Trebuchet MS", color: C.navy, bold: true, margin: 0
    });

    // Ranked table approach — more readable than a chart
    const repos = [
      { rank: "#1", name: "NousResearch/hermes-agent", desc: "The agent that grows with you", stars: "1,347", forks: "101", pushes: "42", prs: "78", lang: "Python" },
      { rank: "#2", name: "safishamsi/graphify", desc: "AI coding assistant skill — queryable knowledge graph", stars: "742", forks: "50", pushes: "6", prs: "5", lang: "Python" },
      { rank: "#3", name: "VoltAgent/awesome-design-md", desc: "DESIGN.md files for coding agents", stars: "615", forks: "48", pushes: "1", prs: "0", lang: "HTML" },
      { rank: "#4", name: "JuliusBrussee/caveman", desc: "Cuts 75% of tokens by talking like caveman", stars: "300", forks: "11", pushes: "1", prs: "1", lang: "Python" },
      { rank: "#5", name: "shanraisshan/claude-code-best-practice", desc: "Practice made Claude perfect", stars: "304", forks: "23", pushes: "0", prs: "0", lang: "HTML" },
    ];

    // Table header
    const headerOpts = { fill: { color: C.navy }, color: C.white, bold: true, fontSize: 10, fontFace: "Calibri", align: "center", valign: "middle", margin: [2,4,2,4] };
    const cellOpts = (isEven) => ({ fill: { color: isEven ? C.white : "F8FAFC" }, color: C.darkSlate, fontSize: 10, fontFace: "Calibri", valign: "middle", margin: [3,4,3,4] });

    const tableRows = [
      [
        { text: "Rank", options: headerOpts },
        { text: "Repository", options: headerOpts },
        { text: "Stars", options: headerOpts },
        { text: "Forks", options: headerOpts },
        { text: "Pushes", options: headerOpts },
        { text: "PRs", options: headerOpts },
        { text: "Language", options: headerOpts },
      ]
    ];

    repos.forEach((r, i) => {
      const even = i % 2 === 0;
      const co = cellOpts(even);
      const nameOpts = { ...co, bold: true, color: C.teal };
      tableRows.push([
        { text: r.rank, options: { ...co, align: "center", bold: true, color: C.navy } },
        { text: r.name, options: nameOpts },
        { text: r.stars, options: { ...co, align: "center" } },
        { text: r.forks, options: { ...co, align: "center" } },
        { text: r.pushes, options: { ...co, align: "center" } },
        { text: r.prs, options: { ...co, align: "center" } },
        { text: r.lang, options: { ...co, align: "center" } },
      ]);
    });

    slide.addTable(tableRows, {
      x: 0.5, y: 1.15, w: 9.0,
      colW: [0.6, 2.8, 0.8, 0.8, 0.8, 0.7, 0.9],
      border: { pt: 0.5, color: "E2E8F0" },
      autoPage: false
    });

    // Bar chart below the table showing stars comparison
    slide.addChart(pres.charts.BAR, [{
      name: "Stars",
      labels: ["hermes-agent", "graphify", "awesome-design-md", "caveman", "claude-code-best-practice"],
      values: [1347, 742, 615, 300, 304]
    }], {
      x: 0.5, y: 3.5, w: 9.0, h: 1.85,
      barDir: "bar",
      chartColors: [C.teal],
      chartArea: { fill: { color: C.white }, roundedCorners: true },
      catAxisLabelColor: C.darkSlate,
      catAxisLabelFontSize: 9,
      valAxisLabelColor: C.midGray,
      valAxisLabelFontSize: 8,
      valGridLine: { color: "E2E8F0", size: 0.5 },
      catGridLine: { style: "none" },
      showValue: true,
      dataLabelPosition: "outEnd",
      dataLabelColor: C.navy,
      dataLabelFontSize: 9,
      showLegend: false,
    });
  }

  // ══════════════════════════════════════════════════════════════════════
  // SLIDE 4 — Language Distribution (Donut Chart)
  // ══════════════════════════════════════════════════════════════════════
  {
    const slide = pres.addSlide();
    slide.background = { color: C.offWhite };

    slide.addShape(pres.shapes.RECTANGLE, {
      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }
    });

    slide.addText("Python and TypeScript Dominate Trending Repos' Language Mix", {
      x: 0.8, y: 0.3, w: 8.4, h: 0.65,
      fontSize: 24, fontFace: "Trebuchet MS", color: C.navy, bold: true, margin: 0
    });

    // Donut chart
    slide.addChart(pres.charts.DOUGHNUT, [{
      name: "Languages",
      labels: ["Python (7)", "TypeScript (4)", "HTML (2)", "Rust (2)", "Swift (2)", "Shell (1)", "Java (1)", "Unspecified (1)"],
      values: [7, 4, 2, 2, 2, 1, 1, 1]
    }], {
      x: 0.3, y: 1.1, w: 5.0, h: 4.0,
      showPercent: true,
      showTitle: false,
      chartColors: [C.teal, C.blue, C.amber, C.rose, C.purple, C.orange, C.cyan, C.lightGray],
      dataLabelColor: C.darkSlate,
      dataLabelFontSize: 9,
      showLegend: true,
      legendPos: "b",
      legendFontSize: 9,
      legendColor: C.darkSlate,
    });

    // Right panel — insight cards
    const insightX = 5.6, insightW = 4.0;

    slide.addShape(pres.shapes.RECTANGLE, {
      x: insightX, y: 1.2, w: insightW, h: 1.3,
      fill: { color: C.white }, shadow: makeShadow()
    });
    slide.addText("35%", {
      x: insightX + 0.3, y: 1.3, w: 1.2, h: 0.5,
      fontSize: 32, fontFace: "Trebuchet MS", color: C.teal, bold: true, margin: 0
    });
