═══════════════════════════════════════════════════════════════════\n  // SLIDE 7 — Community Engagement (Scatter/Grouped Bar)\n  // ══════════════════════════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.offWhite };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }\n    });\n\n    slide.addText(\"hermes-agent Draws 78 PRs and 42 Pushes — Community Activity Varies Widely\", {\n      x: 0.6, y: 0.3, w: 8.8, h: 0.65,\n      fontSize: 22, fontFace: \"Trebuchet MS\", color: C.navy, bold: true, margin: 0\n    });\n\n    // Grouped bar chart — PRs and Pushes for top repos\n    const chartLabels = [\n      \"hermes-agent\", \"multica\", \"oh-my-codex\", \"graphify\",\n      \"rtk\", \"opendataloader\", \"cc-switch\", \"caveman\",\n      \"reverse-SynthID\", \"Recordly\"\n    ];\n    const prsData = [78, 7, 2, 5, 5, 1, 2, 1, 1, 1];\n    const pushesData = [42, 35, 10, 6, 3, 3, 2, 1, 2, 1];\n\n    slide.addChart(pres.charts.BAR, [\n      { name: \"Pull Requests\", labels: chartLabels, values: prsData },\n      { name: \"Pushes\", labels: chartLabels, values: pushesData },\n    ], {\n      x: 0.3, y: 1.1, w: 6.2, h: 3.5,\n      barDir: \"col\",\n      barGrouping: \"clustered\",\n      chartColors: [C.teal, C.blue],\n      chartArea: { fill: { color: C.white }, roundedCorners: true },\n      catAxisLabelColor: C.darkSlate,\n      catAxisLabelFontSize: 8,\n      catAxisOrientation: \"minMax\",\n      valAxisLabelColor: C.midGray,\n      valAxisLabelFontSize: 9,\n      valGridLine: { color: \"E2E8F0\", size: 0.5 },\n      catGridLine: { style: \"none\" },\n      showLegend: true,\n      legendPos: \"t\",\n      legendFontSize: 10,\n      legendColor: C.darkSlate,\n      showValue: false,\n    });\n\n    // Right panel — key insights\n    const rpX = 6.8, rpW = 2.9;\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rpX, y: 1.1, w: rpW, h: 1.5,\n      fill: { color: C.navy }\n    });\n    slide.addText(\"78\", {\n      x: rpX + 0.2, y: 1.2, w: 1, h: 0.5,\n      fontSize: 36, fontFace: \"Trebuchet MS\", color: C.amber, bold: true, margin: 0\n    });\n    slide.addText(\"PRs for hermes-agent\\nin just 24 hours — dwarfing\\nall other repos combined\", {\n      x: rpX + 0.2, y: 1.7, w: rpW - 0.4, h: 0.75,\n      fontSize: 11, fontFace: \"Calibri\", color: C.lightGray, margin: 0\n    });\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rpX, y: 2.8, w: rpW, h: 1.2,\n      fill: { color: C.darkSlate }\n    });\n    slide.addText(\"8 of 20\", {\n      x: rpX + 0.2, y: 2.9, w: 2, h: 0.4,\n      fontSize: 24, fontFace: \"Trebuchet MS\", color: C.rose, bold: true, margin: 0\n    });\n    slide.addText(\"repos have zero PRs — early-stage\\nor single-author projects riding\\ninitial hype\", {\n      x: rpX + 0.2, y: 3.3, w: rpW - 0.4, h: 0.6,\n      fontSize: 11, fontFace: \"Calibri\", color: C.lightGray, margin: 0\n    });\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: rpX, y: 4.2, w: rpW, h: 0.5,\n      fill: { color: C.teal, transparency: 85 }\n    });\n    slide.addText(\"multica shows 35 pushes — 2nd most active contributor community\", {\n      x: rpX + 0.2, y: 4.25, w: rpW - 0.4, h: 0.4,\n      fontSize: 10, fontFace: \"Calibri\", color: C.teal, margin: 0, valign: \"middle\"\n    });\n  }\n\n  // ══════════════════════════════════════════════════════════════════════\n  // SLIDE 8 — Key Takeaways\n  // ══════════════════════════════════════════════════════════════════════\n  {\n    const slide = pres.addSlide();\n    slide.background = { color: C.navy };\n\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal }\n    });\n\n    slide.addText(\"Key Takeaways: AI Coding Agents Are GitHub's Hottest Category\", {\n      x: 0.8, y: 0.3, w: 8.4, h: 0.65,\n      fontSize: 26, fontFace: \"Trebuchet MS\", color: C.white, bold: true, margin: 0\n    });\n\n    const takeaways = [\n      {\n        title: \"AI coding agents dominate GitHub trending\",\n        body: \"14 of the top 20 repos (70%) are AI coding agent tools, skills, or related resources — an unprecedented concentration in a single theme.\",\n        color: C.teal,\n        icon: icons.robot\n      },\n      {\n        title: \"Claude Code has spawned a full ecosystem overnight\",\n        body: \"At least 7 repos are specifically Claude Code skills, guides, best-practice collections, or multi-tool switchers — rapid community formation around Anthropic's coding tool.\",\n        color: C.blue,\n        icon: icons.code\n      },\n      {\n        title: \"Python leads, but TypeScript is the runner-up\",\n        body: \"Python powers 35% of trending repos (AI/ML core), while TypeScript (20%) drives agent UIs and developer experience layers.\",\n        color: C.purple,\n        icon: icons.insights\n      },\n      {\n        title: \"Community engagement is top-heavy\",\n        body: \"The #1 repo attracted 78 PRs in 24 hours; most repos below #8 show minimal collaborative activity.\",\n        color: C.amber,\n        icon: icons.lightning\n      },\n      {\n        title: \"Token efficiency is a hot sub-theme\",\n        body: \"Multiple repos (caveman, rtk) focus on reducing LLM token consumption — signaling cost-consciousness as AI coding tools scale.\",\n        color: C.rose,\n        icon: icons.chart\n      }\n    ];\n\n    const taStartY = 1.15, taH = 0.78, taGap = 0.1;\n\n    takeaways.forEach((t, i) => {\n      const ty = taStartY + i * (taH + taGap);\n\n      // Card bg\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 0.8, y: ty, w: 8.4, h: taH,\n        fill: { color: C.darkSlate }\n      });\n\n      // Accent left bar\n      slide.addShape(pres.shapes.RECTANGLE, {\n        x: 0.8, y: ty, w: 0.06, h: taH,\n        fill: { color: t.color }\n      });\n\n      // Icon\n      slide.addImage({ data: t.icon, x: 1.1, y: ty + (taH - 0.35) / 2, w: 0.35, h: 0.35 });\n\n      // Title\n      slide.addText(t.title, {\n        x: 1.65, y: ty + 0.08, w: 7.3, h: 0.28,\n        fontSize: 14, fontFace: \"Trebuchet MS\", color: C.white, bold: true, margin: 0\n      });\n\n      // Body\n      slide.addText(t.body, {\n        x: 1.65, y: ty + 0.38, w: 7.3, h: 0.35,\n        fontSize: 10, fontFace: \"Calibri\", color: C.lightGray, margin: 0\n      });\n    });\n\n    // Bottom bar\n    slide.addShape(pres.shapes.RECTANGLE, {\n      x: 0, y: 5.35, w: 10, h: 0.275, fill: { color: C.teal, transparency: 80 }\n    });\n    slide.addText(\"Data: OSSInsight (ossinsight.io)  |  10.6B+ GitHub events  |  Top 20 trending repos, past 24 hours\", {\n      x: 0.8, y: 5.35, w: 8.4, h: 0.275,\n      fontSize: 9, fontFace: \"Calibri\", color: C.lightGray, align: \"center\", valign: \"middle\", margin: 0\n    });\n  }\n\n  // ── Write file ──\n  await pres.writeFile({ fileName: \"/app/output/final_deck.pptx\" });\n  console.log(\"Presentation saved to /app/output/final_deck.pptx\");\n}\n\nmain().catch(err => { console.error(err); process.exit(1); });\n", "numLines": 766, "startLine": 1, "totalLines": 766}}

