18	async function iconToBase64Png(IconComponent, color, size = 256) {
19	  const svg = renderIconSvg(IconComponent, color, size);
20	  const pngBuffer = await sharp(Buffer.from(svg)).png().toBuffer();
21	  return "image/png;base64," + pngBuffer.toString("base64");
22	}
